"""Repair observed omissions in translated privacy disclosures without approving release."""
import json
import xml.etree.ElementTree as ET
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]

def paragraph(locale, index, value, records):
    folder=ROOT/'localization/generated'/('values-b+'+locale.replace('-','+'))
    text=next(e.text for e in ET.parse(folder/'strings.xml').findall('string') if e.attrib['name']=='privacy_body')
    text=records.get(locale,{}).get('privacy_body',text.replace("\\'","'").replace('\\"','"'))
    parts=text.split('\\n\\n');assert len(parts)==5
    parts[index]=value
    records.setdefault(locale,{})['privacy_body']='\\n\\n'.join(parts)

def main():
    p=ROOT/'localization/editorial-overrides.json';r=json.loads(p.read_text(encoding='utf-8'))
    for locale in ['es-ES','es-419']:
        paragraph(locale,2,'Cuando las compras están configuradas, los identificadores de usuario y recibo de compra de Amazon se envían por HTTPS al verificador de Possessory alojado en Cloudflare Workers para comprobar compras y restaurar el acceso. El verificador usa la dirección IP de conexión y un hash de los identificadores para limitar temporalmente la frecuencia de solicitudes. No tiene base de datos de clientes y el registro de solicitudes de la aplicación está desactivado. Cloudflare procesa metadatos de red para operar y proteger su servicio. Amazon gestiona el pago por separado. El acceso verificado sin conexión puede durar hasta 90 días, o hasta que entre en vigor una cancelación verificada anterior; después requiere una actualización en línea.',r)
        paragraph(locale,3,'Los archivos exportados y las copias de seguridad se guardan solo en el destino que elijas, que puede ser un proveedor de documentos en la nube. Las exportaciones normales y las copias ZIP no están cifradas. Las copias protegidas con contraseña usan AES-GCM; las contraseñas no se pueden recuperar. La protección mediante desbloqueo del dispositivo es opcional y no cifra por separado la base de datos ni los archivos adjuntos.',r)
    for locale in ['fr-FR','fr-CA']:
        paragraph(locale,2,'Lorsque les achats sont configurés, les identifiants utilisateur et de reçu d’achat Amazon sont envoyés par HTTPS au service de vérification de Possessory hébergé sur Cloudflare Workers, pour vérifier les achats et rétablir l’accès. Ce service utilise l’adresse IP de connexion et un hachage des identifiants d’achat pour limiter temporairement la fréquence des requêtes. Il n’a pas de base de données clients et la journalisation des requêtes est désactivée. Cloudflare traite les métadonnées réseau pour exploiter et sécuriser son service. Amazon gère séparément les paiements. L’accès vérifié hors ligne peut rester valable jusqu’à 90 jours, ou jusqu’à la prise d’effet d’une annulation vérifiée antérieure, avant qu’une actualisation en ligne soit nécessaire.',r)
        paragraph(locale,3,'Les fichiers exportés et les sauvegardes sont enregistrés uniquement à l’emplacement choisi, qui peut être un service de documents en nuage. Les exports ordinaires et les sauvegardes ZIP ne sont pas chiffrés. Les sauvegardes protégées par mot de passe utilisent AES-GCM ; les mots de passe ne peuvent pas être récupérés. La protection par déverrouillage de l’appareil est facultative et ne chiffre pas séparément la base de données ou les pièces jointes.',r)
        paragraph(locale,4,'Supprimez des enregistrements ou toutes les données locales dans les paramètres. La désinstallation supprime les données privées ; les copies exportées restent à leur emplacement. Conservez une sauvegarde vérifiée avant de désinstaller. Contactez l’assistance pour toute question de confidentialité ou pour supprimer votre correspondance avec elle.',r)
    paragraph('de-DE',0,'Inventar, Haushaltsdaten, Raumfotos, Belege, Wartungsunterlagen und Einstellungen werden im privaten App-Speicher abgelegt. Ein Konto, Werbung oder Analysedienste sind nicht erforderlich. Es wird nichts unbemerkt synchronisiert. Die Belegerkennung läuft lokal in der gewählten Sprache.',r)
    paragraph('de-DE',1,'Spracheingabe ist optional und kann den Netzwerkdienst des Sprachanbieters Ihres Geräts verwenden. Possessory bewahrt keine Audioaufnahmen auf. Fotos, Belege, Notizen und Seriennummern werden nicht an den Kaufprüfungsdienst gesendet.',r)
    paragraph('de-DE',3,'Exporte und Sicherungen werden nur am gewählten Ziel gespeichert; dies kann auch ein Cloud-Dokumentendienst sein. Normale Exporte und ZIP-Sicherungen sind unverschlüsselt. Passwortgeschützte Sicherungen verwenden AES-GCM; Passwörter können nicht wiederhergestellt werden. Der optionale Schutz durch Geräteentsperrung verschlüsselt Datenbank und Anhänge nicht zusätzlich.',r)
    paragraph('it-IT',0,'Inventario, dati delle abitazioni, foto delle stanze, ricevute, documenti di manutenzione e preferenze sono conservati nell’archivio privato dell’app. Non sono necessari account, pubblicità o analisi. Nulla viene sincronizzato senza avvisarti. L’OCR delle ricevute funziona sul dispositivo nella lingua scelta.',r)
    paragraph('it-IT',1,'L’input vocale è facoltativo e può usare il servizio di rete del fornitore vocale del dispositivo. Possessory non conserva registrazioni audio grezze. Foto, ricevute, note e numeri di serie non vengono inviati al servizio di verifica degli acquisti.',r)
    paragraph('it-IT',2,'Quando gli acquisti sono configurati, gli identificativi utente e delle ricevute di acquisto Amazon vengono inviati tramite HTTPS al servizio di verifica di Possessory ospitato su Cloudflare Workers, per verificare gli acquisti e ripristinare l’accesso. Il servizio usa l’indirizzo IP della connessione e un hash degli identificativi per limitare temporaneamente la frequenza delle richieste. Non dispone di un database clienti e la registrazione delle richieste è disattivata. Cloudflare elabora i metadati di rete per gestire e proteggere il servizio. Amazon gestisce separatamente i pagamenti. L’accesso verificato offline può durare fino a 90 giorni, o fino all’efficacia di un annullamento verificato precedente; poi occorre un aggiornamento online.',r)
    paragraph('it-IT',3,'Esportazioni e backup sono salvati solo nella destinazione scelta, che può essere un servizio di documenti cloud. Le esportazioni normali e i backup ZIP non sono cifrati. I backup protetti da password usano AES-GCM; le password non possono essere recuperate. La protezione tramite sblocco del dispositivo è facoltativa e non cifra separatamente database o allegati.',r)
    paragraph('it-IT',4,'Elimina singoli dati o tutti i dati locali nelle Impostazioni. La disinstallazione rimuove i dati privati; le copie esportate restano dove le hai salvate. Conserva un backup verificato prima di disinstallare. Contatta l’assistenza per la privacy o per eliminare la corrispondenza con l’assistenza.',r)
    for locale in ['pt-BR','pt-PT']:
        paragraph(locale,0,'O inventário, os dados das casas, as fotos das divisões, os recibos, os documentos de manutenção e as preferências ficam no armazenamento privado da aplicação. Não é necessária conta, publicidade ou análise. Nada é sincronizado sem o seu conhecimento. O OCR dos recibos funciona localmente no idioma escolhido.',r)
        paragraph(locale,1,'A entrada por voz é opcional e pode utilizar o serviço de rede do fornecedor de reconhecimento de voz do dispositivo. O Possessory não guarda gravações de áudio. Fotos, recibos, notas e números de série não são enviados ao serviço de verificação de compras.',r)
        paragraph(locale,2,'Quando as compras estão configuradas, os identificadores de utilizador e de recibo de compra da Amazon são enviados por HTTPS ao verificador do Possessory alojado no Cloudflare Workers, para verificar compras e restaurar o acesso. O verificador utiliza o endereço IP da ligação e um hash dos identificadores para limitar temporariamente a frequência dos pedidos. Não possui base de dados de clientes e o registo de pedidos está desativado. A Cloudflare processa metadados de rede para operar e proteger o serviço. A Amazon trata dos pagamentos separadamente. O acesso verificado sem ligação pode durar até 90 dias, ou até entrar em vigor um cancelamento verificado anterior; depois é necessária uma atualização online.',r)
        paragraph(locale,3,'As exportações e cópias de segurança são guardadas apenas no destino escolhido, que pode ser um serviço de documentos na nuvem. As exportações normais e as cópias ZIP não são cifradas. As cópias protegidas por palavra-passe utilizam AES-GCM; as palavras-passe não podem ser recuperadas. A proteção por desbloqueio do dispositivo é opcional e não cifra separadamente a base de dados ou os anexos.',r)
        if locale=='pt-BR':
            text=r[locale]['privacy_body']
            for a,b in [('divisões','cômodos'),('aplicação','aplicativo'),('utilizador','usuário'),('alojado','hospedado'),('ligação','conexão'),('pedidos','solicitações'),('registo','registro'),('base de dados','banco de dados'),('palavras-passe','senhas'),('palavra-passe','senha'),('cifradas','criptografadas'),('não cifra','não criptografa')]:text=text.replace(a,b)
            r[locale]['privacy_body']=text
    paragraph('pl-PL',2,'Gdy zakupy są skonfigurowane, identyfikatory użytkownika Amazon i paragonu zakupu są przesyłane przez HTTPS do usługi weryfikacyjnej Possessory na Cloudflare Workers, aby sprawdzić zakup i przywrócić dostęp. Usługa używa adresu IP połączenia i skrótu identyfikatorów zakupu do krótkotrwałego ograniczania liczby żądań. Nie ma bazy klientów, a rejestrowanie żądań aplikacji jest wyłączone. Cloudflare przetwarza metadane sieciowe w celu działania i ochrony usługi. Amazon oddzielnie obsługuje płatności. Zweryfikowany dostęp offline może być ważny do 90 dni lub do wejścia w życie wcześniej zweryfikowanego anulowania; potem wymaga odświeżenia online.',r)
    paragraph('pl-PL',3,'Eksporty i kopie zapasowe są zapisywane tylko w wybranym miejscu, także w usłudze dokumentów w chmurze, jeśli ją wybierzesz. Zwykłe eksporty i kopie ZIP nie są szyfrowane. Kopie chronione hasłem używają AES-GCM; haseł nie można odzyskać. Ochrona przez odblokowanie urządzenia jest opcjonalna i nie szyfruje osobno bazy danych ani załączników.',r)
    paragraph('sv-SE',3,'Exporter och säkerhetskopior sparas bara på den plats du väljer, som kan vara en molntjänst för dokument. Vanliga exporter och ZIP-säkerhetskopior är okrypterade. Lösenordsskyddade säkerhetskopior använder AES-GCM; lösenorden kan inte återställas. Skydd genom upplåsning av enheten är valfritt och krypterar inte databasen eller bilagorna separat.',r)
    paragraph('sv-SE',4,'Radera enskilda poster eller alla lokala data i Inställningar. Avinstallation tar bort privata poster; exporterade kopior finns kvar där du sparade dem. Spara en kontrollerad säkerhetskopia innan du avinstallerar. Kontakta supporten om integritet eller radering av supportkorrespondens.',r)
    paragraph('tr-TR',0,'Envanter, ev kayıtları, oda fotoğrafları, makbuzlar, bakım belgeleri ve tercihler uygulamanın özel depolama alanında tutulur. Hesap, reklam veya analiz gerekmez. Bilginiz dışında eşitleme yapılmaz. Makbuz OCR işlemi seçtiğiniz dilde cihazda çalışır.',r)
    paragraph('tr-TR',1,'Sesli giriş isteğe bağlıdır ve cihazın konuşma sağlayıcısının ağ hizmetini kullanabilir. Possessory ham ses kayıtlarını saklamaz. Fotoğraflar, makbuzlar, notlar ve seri numaraları satın alma doğrulama hizmetine gönderilmez.',r)
    paragraph('tr-TR',2,'Satın alma yapılandırıldığında Amazon kullanıcı ve satın alma makbuzu kimlikleri, satın alımları kontrol etmek ve erişimi geri yüklemek için HTTPS üzerinden Cloudflare Workers üzerindeki Possessory doğrulayıcısına gönderilir. Doğrulayıcı, kısa süreli istek hızı sınırlaması için bağlantı IP adresini ve satın alma kimliklerinin özetini kullanır. Müşteri veritabanı yoktur ve uygulama istek günlükleri kapalıdır. Cloudflare hizmetini işletmek ve korumak için ağ meta verilerini işler. Ödemeleri Amazon ayrı olarak yönetir. Doğrulanmış çevrimdışı erişim 90 güne kadar veya daha önce doğrulanmış bir iptal yürürlüğe girene kadar geçerli kalabilir; ardından çevrimiçi yenileme gerekir.',r)
    paragraph('tr-TR',3,'Dışa aktarımlar ve yedekler yalnızca seçtiğiniz hedefe kaydedilir; bu bir bulut belge sağlayıcısı olabilir. Normal dışa aktarımlar ve ZIP yedekleri şifrelenmez. Parola korumalı yedekler AES-GCM kullanır; parolalar kurtarılamaz. Cihaz kilidiyle koruma isteğe bağlıdır; veritabanını veya ekleri ayrıca şifrelemez.',r)
    paragraph('tr-TR',4,'Ayarlar’dan tek tek kayıtları veya tüm yerel verileri silin. Uygulamayı kaldırmak özel kayıtları siler; dışa aktarılan kopyalar kaydettiğiniz yerde kalır. Uygulamayı kaldırmadan önce doğrulanmış bir yedek tutun. Gizlilik veya destek yazışmalarının silinmesi için desteğe başvurun.',r)
    premium_parts={
      'fr-FR fr-CA': ('Premium est un achat unique sur Amazon, sans abonnement. Le magasin affiche le prix local. L’achat et la restauration nécessitent Internet. ', ' L’inventaire du foyer et les photos de reçus ne sont pas envoyés. Les enregistrements existants, la modification ordinaire, la suppression et la restauration des sauvegardes restent disponibles sans Premium.'),
      'it-IT': ('Premium è un acquisto unico su Amazon, senza abbonamento. Il negozio mostra il prezzo locale. Acquisto e ripristino richiedono Internet. ', ' L’inventario domestico e le foto delle ricevute non vengono inviati. I dati esistenti, le normali modifiche, l’eliminazione e il ripristino dei backup restano disponibili senza Premium.'),
      'pt-BR': ('Premium é uma compra única na Amazon, sem assinatura. A loja mostra o preço local. Compra e restauração exigem internet. ', ' O inventário doméstico e as fotos dos recibos não são enviados. Os registros existentes, a edição comum, a exclusão e a restauração de backups continuam disponíveis sem Premium.'),
      'pt-PT': ('Premium é uma compra única na Amazon, sem subscrição. A loja apresenta o preço local. A compra e o restauro exigem Internet. ', ' O inventário da casa e as fotografias dos recibos não são enviados. Os registos existentes, a edição normal, a eliminação e o restauro de cópias de segurança continuam disponíveis sem Premium.'),
      'pl-PL': ('Premium to jednorazowy zakup w Amazon, bez subskrypcji. Sklep podaje lokalną cenę. Zakup i przywracanie wymagają internetu. ', ' Inwentarz domu i zdjęcia paragonów nie są wysyłane. Istniejące dane, zwykła edycja, usuwanie i przywracanie kopii zapasowych są dostępne bez Premium.'),
    }
    for locales,(intro,ending) in premium_parts.items():
        for locale in locales.split():
            r[locale]['support:premium']=intro+r[locale]['privacy_body'].split('\\n\\n')[2]+ending
    p.write_text(json.dumps(r,ensure_ascii=False,indent=2)+'\n',encoding='utf-8',newline='\n')
    print('Recorded privacy omission repairs; release approval unchanged.')

if __name__=='__main__':main()
